<?php
declare(strict_types=1);
require_once __DIR__.'/application-documents.php';require_once __DIR__.'/google-auth.php';
final class LifeApplicationGoogle {
 public function __construct(private LifeApplications $apps,private mixed $transport=null){$db=$apps->store->db;$db->exec('CREATE TABLE IF NOT EXISTS life_application_google (id INT PRIMARY KEY,token LONGTEXT NOT NULL)');$db->exec('CREATE TABLE IF NOT EXISTS life_application_exports (id VARCHAR(100) PRIMARY KEY,owner_id INT NOT NULL,document_id VARCHAR(32) NOT NULL,url VARCHAR(2048) NOT NULL)');}
 public function status():array{$q=$this->apps->store->db->prepare('SELECT token FROM life_application_google WHERE id=?');$q->execute([$this->apps->store->tenantId]);return ['connected'=>(bool)$q->fetchColumn(),'available'=>LifeGoogleAuth::ready()];}
 public function connect(array $token):void{if(!in_array('https://www.googleapis.com/auth/drive.file',explode(' ',$token['scope']??''),true))throw new LifeError('Google document creation access was not granted.',403);$db=$this->apps->store->db;$q=$db->prepare('SELECT token FROM life_application_google WHERE id=?');$q->execute([$this->apps->store->tenantId]);$old=$q->fetchColumn();if(empty($token['refresh_token'])&&$old)$token['refresh_token']=LifeGoogleAuth::decrypt($old,$this->apps->store->tenantId)['refresh_token']??'';if(empty($token['refresh_token']))throw new LifeError('Allow access to create your document copies.',403);$encrypted=LifeGoogleAuth::encrypt($token,$this->apps->store->tenantId);if($old!==false)$db->prepare('UPDATE life_application_google SET token=? WHERE id=?')->execute([$encrypted,$this->apps->store->tenantId]);else $db->prepare('INSERT INTO life_application_google VALUES (?,?)')->execute([$this->apps->store->tenantId,$encrypted]);}
 public function disconnect():void{$this->apps->store->db->prepare('DELETE FROM life_application_google WHERE id=?')->execute([$this->apps->store->tenantId]);}
 public function export(array $input):array{$doc=LifeApplications::find($this->apps->read()['state'],'documents',$input['documentId']??'',true);if(!in_array($doc['mime'],['text/plain','application/vnd.openxmlformats-officedocument.wordprocessingml.document'],true))throw new LifeError('Create an editable Word or text draft first.');$requestId=LifeStore::text($input['requestId']??'',100,true);if(!preg_match('/^[A-Za-z0-9_-]{8,100}$/D',$requestId))throw new LifeError('Invalid document export request.');$key=hash('sha256',$this->apps->store->tenantId.':'.$requestId);$docs=new LifeApplicationDocuments($this->apps);$lock=fopen($docs->dir().'/google-export.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))throw new LifeError('A document is exporting. Please wait.',409);try{$q=$this->apps->store->db->prepare('SELECT document_id,url FROM life_application_exports WHERE id=? AND owner_id=?');$q->execute([$key,$this->apps->store->tenantId]);$saved=$q->fetch(PDO::FETCH_ASSOC);if($saved){if($saved['document_id']!==$doc['id'])throw new LifeError('This export request belongs to another document.',409);return ['url'=>$saved['url'],'documentId'=>$doc['id'],'saved'=>true];}
  if($this->transport)$result=($this->transport)($doc,$key);else{$q=$this->apps->store->db->prepare('SELECT token FROM life_application_google WHERE id=?');$q->execute([$this->apps->store->tenantId]);$encrypted=$q->fetchColumn();if(!$encrypted)throw new LifeError('Connect Google Docs before exporting.',403);$client=LifeGoogleAuth::client();$token=LifeGoogleAuth::decrypt($encrypted,$this->apps->store->tenantId);$client->setAccessToken($token);if($client->isAccessTokenExpired()){$renewed=$client->fetchAccessTokenWithRefreshToken($token['refresh_token']??'');if(isset($renewed['error']))throw new LifeError('Reconnect Google Docs.',403);$renewed['refresh_token']=$token['refresh_token'];$client->setAccessToken($renewed);$this->apps->store->db->prepare('UPDATE life_application_google SET token=? WHERE id=?')->execute([LifeGoogleAuth::encrypt($renewed,$this->apps->store->tenantId),$this->apps->store->tenantId]);}$http=$client->authorize();$query="trashed = false and appProperties has { key='lifeExport' and value='".$key."' }";$response=$http->request('GET','https://www.googleapis.com/drive/v3/files',['query'=>['q'=>$query,'fields'=>'files(id,webViewLink,appProperties)'],'timeout'=>20,'http_errors'=>false]);if($response->getStatusCode()!==200)throw new LifeError('Google could not verify earlier exports. No new document was created.',503);$found=json_decode((string)$response->getBody(),true);$result=$found['files'][0]??null;if($result&&($result['appProperties']['lifeDocument']??'')!==$doc['id'])throw new LifeError('This export request belongs to another document.',409);if(!$result){$path=$docs->path($doc);if(!is_file($path))throw new LifeError('The source document is unavailable.',404);$boundary='life'.bin2hex(random_bytes(12));$metadata=json_encode(['name'=>$doc['name'],'mimeType'=>'application/vnd.google-apps.document','appProperties'=>['lifeExport'=>$key,'lifeDocument'=>$doc['id']]],JSON_THROW_ON_ERROR);$body='--'.$boundary."\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n".$metadata."\r\n--".$boundary."\r\nContent-Type: ".$doc['mime']."\r\n\r\n".file_get_contents($path)."\r\n--".$boundary."--\r\n";$response=$http->request('POST','https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,webViewLink',['body'=>$body,'headers'=>['Content-Type'=>'multipart/related; boundary='.$boundary],'timeout'=>40,'http_errors'=>false]);if($response->getStatusCode()<200||$response->getStatusCode()>=300)throw new LifeError('Google could not create the editable copy. Your saved draft remains available.',503);$result=json_decode((string)$response->getBody(),true);}}
  $remote=$result['id']??'';if(!is_string($remote)||!preg_match('/^[A-Za-z0-9_-]{5,200}$/D',$remote))throw new LifeError('Google did not return a verified document.',503);$url='https://docs.google.com/document/d/'.$remote.'/edit';$this->apps->store->db->prepare('INSERT INTO life_application_exports VALUES (?,?,?,?)')->execute([$key,$this->apps->store->tenantId,$doc['id'],$url]);return ['url'=>$url,'documentId'=>$doc['id'],'saved'=>true];
 }finally{flock($lock,LOCK_UN);fclose($lock);}}
}
